/** u8 GetBattlerForBattleScript(u8 caseId) */
export function GetBattlerForBattleScript(caseId: any): any {
  let ret: any = 0;
      switch (caseId)
      {
      case (0):
          ret = gBattlerTarget;
          break;
      case (1):
          ret = gBattlerAttacker;
          break;
      case (2):
          ret = gEffectBattler;
          break;
      case (7):
          ret = 0;
          break;
      case (10):
          ret = gBattleScripting.battler;
          break;
      case (3):
          ret = gBattlerFainted;
          break;
      case (5):
          ret = gBattlerFainted;
          break;
      case (4):
      case (6):
      case (8):
      case (9):
      case (11):
          ret = GetBattlerAtPosition(B_POSITION_PLAYER_LEFT);
          break;
      case (12):
          ret = GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT);
          break;
      case (13):
          ret = GetBattlerAtPosition(B_POSITION_PLAYER_RIGHT);
          break;
      case (14):
          ret = GetBattlerAtPosition(B_POSITION_OPPONENT_RIGHT);
          break;
      }
      return ret;
}

/** void PressurePPLose(u8 target, u8 attacker, u16 move) */
export function PressurePPLose(target: any, attacker: any, move: any): any {
  let moveIndex: any = null;

      if (gBattleMons[target].ability != (46))
          return;

      for (moveIndex = 0; moveIndex < (4); moveIndex++)
      {
          if (gBattleMons[attacker].moves[moveIndex] == move)
              break;
      }

      if (moveIndex == (4))
          return;

      if (gBattleMons[attacker].pp[moveIndex] != 0)
          gBattleMons[attacker].pp[moveIndex]--;

      if (MOVE_IS_PERMANENT(attacker, moveIndex))
      {
          gActiveBattler = attacker;
          BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_PPMOVE1_BATTLE + moveIndex, 0, 1,gBattleMons[gActiveBattler].pp[moveIndex]);
          MarkBattlerForControllerExec(gActiveBattler);
      }
}

